import { rotations, seedTasks } from "./data.js";
(()=>{
  const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)], today=new Date(); today.setHours(0,0,0,0);
  const iso=d=>{const x=new Date(d.getTime()-d.getTimezoneOffset()*60000);return x.toISOString().slice(0,10)}, parse=s=>new Date(s+'T00:00:00'), fmt=(s,opt={day:'numeric',month:'short'})=>parse(s).toLocaleDateString('pt-BR',opt), id=()=>Math.random().toString(36).slice(2,10);
  const seed=seedTasks.map(x=>({id:id(),...x}));
  let tasks=JSON.parse(localStorage.getItem('rotinamed.tasks')||'null')||seed, notices=JSON.parse(localStorage.getItem('rotinamed.notices')||'null')||[{id:id(),title:'Respeite seu ritmo',text:'Pausas também fazem parte de um bom plano de estudos.'}], filter='today', month=new Date(today.getFullYear(),today.getMonth(),1), weekAnchor=new Date(today), selectedDay=iso(today);
  const save=()=>localStorage.setItem('rotinamed.tasks',JSON.stringify(tasks)), saveNotices=()=>localStorage.setItem('rotinamed.notices',JSON.stringify(notices));
  const current=rotations.find(r=>iso(today)>=r.start&&iso(today)<=r.end)||rotations.find(r=>r.start>iso(today))||rotations.at(-1);
  $('#currentRotation').textContent=current.name; $('#currentDates').textContent=`${fmt(current.start,{day:'numeric',month:'long'})} — ${fmt(current.end,{day:'numeric',month:'long',year:'numeric'})}`;
  const prog=Math.max(0,Math.min(100,((today-parse(current.start))/(parse(current.end)-parse(current.start)))*100));$('#rotationProgress').style.width=prog+'%';
  $('#todayLabel').textContent=today.toLocaleDateString('pt-BR',{weekday:'long',day:'numeric',month:'long'}).toUpperCase();
  function renderTasks(){const day=iso(today), sorted=[...tasks].sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));const upcoming=sorted.filter(t=>!t.done&&t.date>=day);let list=filter==='today'?sorted.filter(t=>t.date===day):filter==='selected'?sorted.filter(t=>t.date===selectedDay):filter==='upcoming'?upcoming:sorted;$('#taskPanelTitle').textContent=filter==='selected'?`Atividades de ${fmt(selectedDay,{day:'numeric',month:'long'})}`:'Seu plano de estudos';$('#taskList').innerHTML=list.length?list.map(taskHTML).join(''):'<div class="empty">'+(filter==='selected'?'Nenhuma atividade neste dia.':'Tudo em dia por aqui. Que tal planejar o próximo passo?')+'</div>';const all=$('#allTaskList');all.innerHTML=sorted.length?sorted.map(taskHTML).join(''):'<div class="empty">Nenhuma atividade ainda. Crie a primeira e organize sua semana.</div>';$$('.check').forEach(c=>c.onchange=()=>{const t=tasks.find(x=>x.id===c.dataset.id);if(t){t.done=c.checked;save();renderAll()}});$$('.task-edit').forEach(b=>b.onclick=()=>editTask(b.dataset.id));$('#navCount').textContent=upcoming.length;const done=tasks.filter(t=>t.done).length;$('#doneCount').textContent=done;$('#todayCount').textContent=tasks.filter(t=>t.date===day&&!t.done).length;$('#weekCount').textContent=tasks.filter(t=>{let d=parse(t.date);let start=new Date(today);start.setDate(start.getDate()-((start.getDay()+6)%7));let end=new Date(start);end.setDate(end.getDate()+7);return d>=start&&d<end&&!t.done}).length;$('#welcomeDone').textContent=done;$('#welcomeLeft').textContent=upcoming.length;}
  function taskHTML(t){let tag=t.category==='Revisão'?'lav':t.category==='Pessoal'?'peach':'';return `<div class="task ${t.done?'done':''}"><input class="check" type="checkbox" ${t.done?'checked':''} data-id="${t.id}" aria-label="Marcar ${esc(t.title)} como concluída"><div class="task-main"><div class="task-title">${esc(t.title)}</div><div class="task-meta"><span>${fmt(t.date,{day:'numeric',month:'short'})}${t.time?' · '+t.time:''}</span><span class="tag ${tag}">${esc(t.category)}</span>${t.priority==='Urgente'?'<span style="color:#c46c5c;font-weight:700">Urgente</span>':''}</div></div><button class="task-edit" data-id="${t.id}" aria-label="Editar atividade">···</button></div>`}
  function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
  function renderNotice(){ $('#noticeList').innerHTML=notices.map(n=>`<div class="notice"><span class="notice-icon">✦</span><div style="flex:1"><b>${esc(n.title)}</b><p>${esc(n.text||'Seu lembrete pessoal.')}</p></div><button class="task-edit" data-notice="${n.id}" aria-label="Excluir lembrete">×</button></div>`).join('')||'<div class="empty">Sem lembretes por enquanto.</div>';$$('[data-notice]').forEach(b=>b.onclick=()=>{notices=notices.filter(n=>n.id!==b.dataset.notice);saveNotices();renderNotice()}) }
  function renderMonth(){const y=month.getFullYear(),m=month.getMonth(),first=new Date(y,m,1),offset=(first.getDay()+6)%7,days=new Date(y,m+1,0).getDate();$('#monthTitle').textContent=month.toLocaleDateString('pt-BR',{month:'long',year:'numeric'});const names=['S','T','Q','Q','S','S','D'];let html=names.map(n=>`<div class="day-name">${n}</div>`).join('');for(let i=0;i<offset;i++)html+='<div></div>';for(let d=1;d<=days;d++){const date=iso(new Date(y,m,d)),isToday=date===iso(today),sel=date===selectedDay,has=tasks.some(t=>t.date===date);html+=`<button class="cal-day ${isToday?'today':''} ${sel?'selected':''} ${has?'event':''}" data-date="${date}">${d}</button>`}$('#miniCalendar').innerHTML=html;$$('.cal-day').forEach(b=>b.onclick=()=>{selectedDay=b.dataset.date;filter='selected';$$('.task-tabs button').forEach(x=>x.classList.remove('active'));renderMonth();renderTasks()})}
  function renderWeek(){const start=new Date(weekAnchor);start.setDate(start.getDate()-((start.getDay()+6)%7));const end=new Date(start);end.setDate(end.getDate()+6);$('#weekTitle').textContent=`${fmt(iso(start),{day:'numeric',month:'short'})} — ${fmt(iso(end),{day:'numeric',month:'short',year:'numeric'})}`;$('#weekGrid').innerHTML=Array.from({length:7},(_,i)=>{let d=new Date(start);d.setDate(d.getDate()+i);let key=iso(d),items=tasks.filter(t=>t.date===key);return `<div class="week-col"><header>${d.toLocaleDateString('pt-BR',{weekday:'short',day:'numeric'})}</header>${items.map(t=>`<div class="week-event">${esc(t.title)}<small>${t.time||'Sem horário'}</small></div>`).join('')}<button class="text-btn" data-add-date="${key}">＋</button></div>`}).join('');$$('[data-add-date]').forEach(b=>b.onclick=()=>openTask(null,b.dataset.addDate))}
  function renderRotations(){ $('#rotationTable').innerHTML=rotations.map(r=>{let status=today<parse(r.start)?'A seguir':today>parse(r.end)?'Concluído':'Em andamento';return `<tr><td><b>${r.name}</b></td><td>${fmt(r.start,{day:'2-digit',month:'2-digit',year:'2-digit'})} a ${fmt(r.end,{day:'2-digit',month:'2-digit',year:'2-digit'})}</td><td><span class="group">${status}</span></td></tr>`}).join('');let next=rotations.find(r=>parse(r.start)>today);$('#nextRotation').textContent=next?next.name.split(' ')[0]:'—';$('#nextRotationDate').textContent=next?`começa em ${fmt(next.start,{day:'numeric',month:'short'})}`:'Ciclo em andamento'}
  function renderAll(){renderTasks();renderNotice();renderMonth();renderWeek();renderRotations()}
  function openTask(t=null,date=iso(today)){const f=$('#taskForm');f.reset();$('#taskId').value=t?.id||'';$('#titleInput').value=t?.title||'';$('#dateInput').value=t?.date||date;$('#timeInput').value=t?.time||'';$('#categoryInput').value=t?.category||'Estudo';$('#priorityInput').value=t?.priority||'Normal';$('#notesInput').value=t?.notes||'';$('#dialogTitle').textContent=t?'Editar atividade':'Nova atividade';$('#deleteTask').hidden=!t;$('#taskDialog').showModal()}
  function editTask(taskId){openTask(tasks.find(t=>t.id===taskId))}
  $('#taskForm').onsubmit=e=>{e.preventDefault();let task={id:$('#taskId').value||id(),title:$('#titleInput').value.trim(),date:$('#dateInput').value,time:$('#timeInput').value,category:$('#categoryInput').value,priority:$('#priorityInput').value,notes:$('#notesInput').value.trim(),done:false};let i=tasks.findIndex(t=>t.id===task.id);if(i>=0)task.done=tasks[i].done;if(i>=0)tasks[i]=task;else tasks.push(task);save();$('#taskDialog').close();renderAll()};$('#deleteTask').onclick=()=>{tasks=tasks.filter(t=>t.id!==$('#taskId').value);save();$('#taskDialog').close();renderAll()};$('#closeDialog').onclick=()=>$('#taskDialog').close();$('#newTask').onclick=$('#newTask2').onclick=$('#newTask3').onclick=$('#newTop').onclick=()=>openTask();
  $$('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;$$('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));renderMonth();renderTasks()});$$('.nav button').forEach(b=>b.onclick=()=>{$$('.nav button').forEach(x=>x.classList.toggle('active',x===b));$$('.view').forEach(v=>v.classList.toggle('active',v.id==='view-'+b.dataset.view));$('#crumbName').textContent=b.textContent.trim().replace(/\d+$/,'').trim()});
  $('#prevMonth').onclick=()=>{month=new Date(month.getFullYear(),month.getMonth()-1,1);renderMonth()};$('#nextMonth').onclick=()=>{month=new Date(month.getFullYear(),month.getMonth()+1,1);renderMonth()};$('#weekPrev').onclick=()=>{weekAnchor.setDate(weekAnchor.getDate()-7);renderWeek()};$('#weekNext').onclick=()=>{weekAnchor.setDate(weekAnchor.getDate()+7);renderWeek()};$('#weekToday').onclick=()=>{weekAnchor=new Date(today);renderWeek()};
  $('#newNotice').onclick=()=>$('#noticeDialog').showModal();$('#closeNotice').onclick=()=>$('#noticeDialog').close();$('#noticeForm').onsubmit=e=>{e.preventDefault();notices.push({id:id(),title:$('#noticeTitle').value.trim(),text:$('#noticeText').value.trim()});saveNotices();e.target.reset();$('#noticeDialog').close();renderNotice()};
  $('#themeBtn').onclick=()=>{let dark=document.documentElement.dataset.theme!=='dark';document.documentElement.dataset.theme=dark?'dark':'light';localStorage.setItem('rotinamed.theme',dark?'dark':'light');$('#themeBtn').textContent=dark?'☼':'☾'};if(localStorage.getItem('rotinamed.theme')==='dark'){document.documentElement.dataset.theme='dark';$('#themeBtn').textContent='☼'}
  $('#notifyBtn').onclick=async()=>{if(!('Notification'in window)){alert('Seu navegador não oferece notificações.');return}let p=await Notification.requestPermission();if(p==='granted'){new Notification('Meu Ritmo',{body:'Avisos ativados. Confira suas atividades do dia!'});$('#notifyBtn').textContent='♧'}else alert('As notificações não foram autorizadas pelo navegador.')};
  $('#assistantForm').onsubmit=e=>{e.preventDefault();const q=$('#assistantInput').value.trim();if(!q)return;const low=q.toLowerCase();let reply;if(/cansad|ansios|estress|descans|pausa/.test(low))reply='Faça uma pausa curta e sem culpa. Depois, escolha uma tarefa pequena e possível para retomar com calma.';else if(/revis|estud|organ|planej|mat[eé]ria|prova/.test(low))reply='Tente dividir o tema em três blocos: 25 minutos para revisar um tópico, 5 minutos de pausa e 15 minutos para questões. Anote dúvidas para revisar depois.';else reply='Vamos por partes: escreva o que precisa fazer, escolha o próximo passo de até 30 minutos e reserve um horário realista. Quer transformar isso em uma atividade?';$('#assistantReply').textContent=reply;$('#assistantInput').value=''};
  renderAll();
})();
